// Exact upstream anchors from v0.1.7-nightly.20261102.4066.
export const source = {
  "packages/provider-opencode/src/server/driver.ts": "import * as Deferred from \"effect/Deferred\";\nimport * as Stream from \"effect/Stream\";\n\nopenCode2Server.withConnection(({ client, events }) =>\n          const scanned = yield* Deferred.make<void>();\n          const pending = new Set([\"command.updated\", \"skill.updated\"]);\n          const stream = yield* events.pipe(Effect.option);\n          if (stream._tag === \"Some\") {\n            yield* stream.value.pipe(\n              Stream.runForEach((event) =>\n                \"location\" in event &&\n                event.location?.directory === cwd &&\n                pending.delete(event.type) &&\n                pending.size === 0\n                  ? Deferred.succeed(scanned, undefined)\n                  : Effect.void,\n              ),\n              Effect.ignore,\n              Effect.forkScoped,\n            );\n          }\n\n            Deferred.await(scanned),\n",
  "packages/provider-opencode/src/server/status.ts": "/**\n * A server scans a directory it has not served yet in the background: its first read lists\n * no commands at all (not even the built-ins), and `command.updated` plus `skill.updated`\n * for the directory end the scan. `scanned` must be listening before `read` runs, since\n * the read is what starts the scan.\n */\n\n  function* <E>(read: Effect.Effect<OpenCode2Workspace, E>, scanned: Effect.Effect<void>) {\n    const first = yield* read;\n    if (first.commands.length > 0) return first;\n    yield* scanned.pipe(Effect.timeoutOption(\"10 seconds\"));\n    return yield* read;\n  },\n"
};
